-- ======================================================================
-- Practice data · People vs sessions (lesson-02)
-- Run this in Supabase: SQL Editor -> New query -> paste -> Run.
-- Generated by the course. Every row here is marked is_synthetic = true.
-- ======================================================================
-- Removes the previous practice data (only rows marked is_synthetic).
-- Your own test runs and real participants are never touched.
delete from public.sessions where is_synthetic;


select 'sessions' as table_name, count(*) from public.sessions where is_synthetic
union all select 'clicks', count(*) from public.clicks c join public.sessions s using (session_id) where s.is_synthetic
union all select 'selections', count(*) from public.selections x join public.sessions s using (session_id) where s.is_synthetic
union all select 'identities', count(*) from public.identities i join public.sessions s using (session_id) where s.is_synthetic;
